import assert from 'node:assert/strict';import {castSealIssues} from '../src/engine/castseal';
const spec:any={open:{ids:['open']},shut:{ids:['before']}},calls:string[]=[];
const issues=castSealIssues(spec,id=>{calls.push(id);if(id==='open')spec.shut={ids:['after']};return false;});
assert.deepEqual(calls,['open','before']);assert.deepEqual(issues,["open.ids names no skill 'open'","shut.ids names no skill 'before'"]);
console.log(JSON.stringify({calls,issues,finalShut:spec.shut}));

conversion.helperSource:
import assert from 'node:assert/strict';import {bootSimEngine,makeSimWorld} from '../src/sim/arena';import {makeSkillInstance,registerConvertRule} from '../src/engine/skills';import {SKILLS} from '../src/data/skills';
bootSimEngine();const w=makeSimWorld('warrior',315001),before=SKILLS.firebolt,replacement={...before,name:'Replacement face'};
registerConvertRule('sdk-live-face',()=>{SKILLS.firebolt=replacement;return true;});
const host=makeSkillInstance({...SKILLS.ruin,convert:{when:'sdk-live-face',skillId:'firebolt'}},1,0);
try{const face=w.slotFaceOf(w.player,host);assert.equal(face,replacement);console.log(JSON.stringify({skill:face.id,name:face.name,sameIdentity:face===replacement}));}finally{SKILLS.firebolt=before;}
